  var SPRITE = null;
  var DATA = {"pyeongga":{"name":"평가계획 도우미","example":"API 키는 어떻게 만들어요?","bubble":"처음이세요? 평가계획 도우미 <b>사용법</b>, 제가 알려 드릴게요!","hello":["에헴, 반가워요! 저는 **AI선비**예요.","이 도우미는 **작년 평가계획**의 내용을 **올해 학교 양식**에 칸칸이 옮겨 적어 줘요. 무엇이 궁금한가요? 아래 버튼을 누르거나 편하게 물어보세요."],"quick":["start","what","ready","connect","blocked","empty","privacy"],"topics":[{"id":"what","q":"이게 뭐 하는 프로그램이에요?","keys":["뭐하는","무엇","소개","기능","뭐야","뭔가요","뭐예요","하는거"],"pose":"wave","a":["학교에서는 해마다 **평가계획**이라는 한/글 문서를 새 양식에 다시 써요. 작년 내용을 칸마다 복사해서 붙이려면 시간이 아주 오래 걸리죠.","이 도우미가 그 일을 대신해요. 작년 파일과 올해 양식을 넣으면, 올해 양식의 **예시가 적힌 칸**에 작년 내용을 알맞게 채워 넣어요. 표 모양, 색, 메모는 그대로 둬요."],"next":["start","ready"]},{"id":"ready","q":"무엇을 준비해야 해요?","keys":["준비","필요한","준비물","파일","양식","hwp","한글파일"],"a":["준비물은 두 가지예요."],"steps":["**올해 양식**: 학교에서 내려온 빈 평가계획 양식 파일이에요. 이건 꼭 있어야 해요.","**작년 평가계획**: 작년에 내가 쓴 평가계획 한/글 파일이에요. 있으면 넣고, 없으면 빼도 돼요."],"tip":"한/글 창에서 바로 채워지게 하려면 Windows 10·11 컴퓨터와 한컴오피스 한/글이 있어야 해요. 없으면 \"설치 없이 파일로 작성하기\"를 쓰면 돼요.","spot":[{"text":"올해 양식"}],"next":["start","blocked"]},{"id":"start","q":"처음부터 차근차근 알려 주세요","keys":["처음","사용법","어떻게","순서","방법","시작","차근차근","하는법","쓰는법"],"a":["좋아요, 순서대로 따라오세요!"],"steps":["**AI 연결 방법 고르기**: 처음 화면의 세 가지 중 하나를 골라요. 잘 모르겠으면 아래쪽 \"AI 없이 기본 기능으로 작성하기\"를 눌러도 시작할 수 있어요.","(한/글 창에서 바로 쓰고 싶다면) \"도우미 설치하기\"로 프로그램을 받아 설치하고 \"설치했어요 · 도우미 연결 확인\"을 눌러요.","**파일 두 개 넣기**: \"작년 평가계획\" 칸과 \"올해 양식\" 칸에 파일을 끌어다 놓거나, 칸을 눌러 골라요.","**\"작성하기\"** 를 누르면 한/글 창이 열리고 칸이 하나씩 채워지는 모습이 보여요. 설치가 안 되는 컴퓨터라면 \"설치 없이 파일로 작성하기\"를 눌러요.","화면 위쪽 **1 파일 → 2 확인 → 3 작성 → 4 저장** 순서를 따라가요. 도우미가 물어보는 것(예: 주당 시수)에 답하면 돼요.","마지막 \"문서를 끝내려면\" 목록을 보고 남은 칸을 손본 뒤, 문서를 한 번 훑어보고 제출해요."],"spot":[{"text":"작년 평가계획"}],"next":["connect","steps4","empty"]},{"id":"connect","q":"AI 연결은 무엇을 골라요?","keys":["연결","ai","고르","골라","어떤거","claude","codex","gemini","클로드","코덱스","제미나이","지피티"],"a":["세 가지 중 내 상황에 맞는 것 **하나만** 고르면 돼요."],"steps":["**설치된 AI로 연결**: 컴퓨터에 Claude Code, Codex CLI, Gemini CLI 중 하나가 깔려 있고 내 계정으로 로그인해 두었다면 이걸 골라요.","**API 키로 연결**: AI를 ChatGPT, Gemini 같은 웹사이트에서만 써 봤다면 이걸 골라요. \"API 키\"라는 전용 열쇠를 만들어 붙여 넣어요.","**연수 코드**: 연수에서 강사님께 연결용 코드를 받았다면 이걸 골라요."],"tip":"AI 없이도 기본 기능은 쓸 수 있어요. \"AI 없이 기본 기능으로 작성하기\"를 누르면 돼요.","spot":[{"text":"API 키로 연결"},{"text":"연결 확인·설정"}],"spotMiss":"연결 고르는 창이 닫혀 있어요. 화면 위쪽 \"연결 확인·설정\" 버튼을 누르면 다시 열려요.","next":["apikey","cli","code","noai"]},{"id":"apikey","q":"API 키는 어떻게 만들어요?","keys":["api","키","apikey","열쇠","발급","에이피아이"],"a":["API 키는 이 도우미가 AI에게 질문할 때 쓰는 **전용 열쇠**예요. 평소 로그인 비밀번호와는 달라요."],"steps":["\"API 키로 연결\"을 누르고 사용할 AI(Gemini 또는 Claude)를 골라요.","\"Gemini API 키 발급받기\"를 눌러 Google 계정으로 로그인해요.","API 키 페이지에서 \"API 키 만들기\"를 누르거나, 이미 있는 키를 복사해요.","이 화면으로 돌아와 칸에 붙여 넣고 \"연결 확인 후 사용\"을 눌러요."],"tip":"연결되면 이 브라우저가 키를 기억해요. 학교 계정에서 권한이 없다고 나오면 학교 관리자에게 물어보세요. 무료로 쓸 수 있는 양과 요금은 AI 회사 안내를 확인해요.","spot":[{"text":"API 키로 연결"}],"next":["connect","privacy"]},{"id":"cli","q":"Claude Code·Codex CLI가 뭐예요?","keys":["cli","클로드코드","claudecode","codexcli","geminicli","명령어","터미널"],"pose":"wave","a":["컴퓨터에 설치해서 쓰는 AI 도구 이름이에요. **CLI**는 버튼 대신 글자로 명령을 입력하는 방식이에요.","걱정 마세요. 이 도우미와 연결하면 도우미가 대신 질문하니까 직접 명령을 칠 필요가 없어요.","이 방법을 쓰려면 그 AI 프로그램에 **내 계정으로 로그인**해 두어야 해요. 브라우저에서만 로그인한 상태로는 연결되지 않아요."],"tip":"이름이 낯설고 설치한 적도 없다면 \"API 키로 연결\"을 고르면 돼요.","next":["apikey","connect"]},{"id":"code","q":"연수 코드는 뭐예요?","keys":["연수코드","연수","코드","강사","입장"],"pose":"wave","a":["연수 코드는 강사님이 준비한 AI를 함께 쓰는 **입장 코드**예요. 한 번 쓰고 끝나는 게 아니라, 정해진 기간과 사용 한도 안에서 여러 번 쓸 수 있어요.","\"연수 코드\"를 누르고 받은 코드를 넣은 뒤 \"코드 확인 후 사용\"을 눌러요. 강사님이 연수용 연결을 켜 두어야 쓸 수 있어요."],"spot":[{"text":"연수 코드"}],"next":["connect"]},{"id":"noai","q":"AI 없이도 쓸 수 있어요?","keys":["ai없이","없이","기본기능","안쓰","무료"],"pose":"cheer","a":["네, 쓸 수 있어요! 연결 창 아래쪽 **\"AI 없이 기본 기능으로 작성하기\"** 를 누르면 돼요. AI를 연결하면 문서의 뜻을 더 잘 읽도록 도와주고, 연결하지 않으면 기본 기능만으로 옮겨 적어요."],"spot":[{"text":"AI 없이 기본 기능으로 작성하기"}],"next":["start"]},{"id":"install","q":"도우미 설치는 어떻게 해요?","keys":["설치","다운","깔아","깔기","프로그램","exe","업데이트","도우미설치"],"steps":["Windows 10·11 컴퓨터에 한컴오피스 한/글이 있는지 확인해요.","\"도우미 설치하기\"를 눌러 설치 파일을 받아요. 예전에 설치했다면 최신 버전으로 다시 받아 업데이트해요.","받은 파일을 열어 설치를 끝내요.","이 화면으로 돌아와 \"설치했어요 · 도우미 연결 확인\"을 눌러요.","브라우저가 \"도우미 열기\"나 \"로컬 네트워크 접근\"을 물어보면 **허용**을 눌러요. 허용해야 연결돼요."],"spot":[{"text":"도우미 설치하기"},{"text":"연결 확인·설정"}],"next":["blocked","start"]},{"id":"blocked","q":"학교 컴퓨터라 설치가 안 돼요","keys":["안돼","안되","막혀","막힘","막혔","막힌","막아","못깔","안깔","학교컴퓨터","학교pc","차단","스마트앱","오류","에러","실행이안","설치가안","관리자","안열려"],"pose":"think","a":["학교 컴퓨터는 설치가 막혀 있는 경우가 많아요. 이럴 땐 두 가지 방법이 있어요."],"steps":["**설치 없이 쓰기**: 파일 두 개를 넣고 \"설치 없이 파일로 작성하기\"를 눌러요. 브라우저 안에서 양식에 바로 써서 완성된 HWP 파일을 내려받아요. 받은 파일은 한/글에서 열어 확인해요.","설치가 꼭 필요하면 학교 정보 담당(관리자) 선생님께 물어보세요."],"tip":"\"설치 없이 파일로 작성하기\"로는 표를 늘리는 작업을 못 해요. 표가 모자라면 한/글에서 직접 늘려야 해요.","spot":[{"text":"설치 없이 파일로 작성하기"}],"next":["install","empty"]},{"id":"steps4","q":"1 파일 · 2 확인 · 3 작성 · 4 저장은 뭐예요?","keys":["단계","확인단계","저장","작성단계","진행","4저장","1파일"],"a":["화면 위쪽 숫자는 지금 어디쯤 왔는지 알려 주는 **길 안내판**이에요."],"steps":["**파일**: 작년 평가계획과 올해 양식을 넣어요.","**확인**: 도우미가 양식에서 읽어 낸 것(메모, 색칠한 칸, 정할 것)을 보여 줘요. 물어보는 것에 답해요. 예를 들어 주당 시수를 넣으면 계산해서 채워요.","**작성**: 한/글 창에서 칸이 채워져요.","**저장**: 검사 결과를 보고 저장해요. 꼭 고쳐야 할 것이 있으면 먼저 알려 줘요."],"spot":[{"sel":"nav"}],"next":["memo","empty"]},{"id":"empty","q":"빈칸이 남았어요","keys":["빈칸","비어","비워","안채워","못채","남은","성취수준","표가모자","표부족","모자라"],"pose":"think","a":["도우미가 **일부러 비워 둔 칸**일 수 있어요. 마지막 화면의 \"문서를 끝내려면\" 목록에서 이유를 알려 줘요."],"steps":["**성취수준을 채우지 못한 칸**: 작년 문서에도, 교육부 성취수준 자료에도 없는 칸이에요. 학교가 따로 준 자료(hwp·hwpx·pdf)가 있으면 넣고, 없으면 직접 채워요.","**예시를 비운 칸**: 다른 과목 예시가 적혀 있었는데 작년에 넣을 값이 없어서 비웠어요.","**확인이 필요해 비워 둔 칸**: 검사에 걸려 도우미가 쓰지 않은 칸이에요. 한/글에서 직접 정해요.","**세부 계획 표가 모자랄 때**: 있는 표를 복사해 붙인 뒤 작년 내용을 옮겨요."],"tip":"어떤 칸이든 마지막엔 사람이 한 번 훑어보는 게 가장 안전해요.","next":["memo","steps4"]},{"id":"memo","q":"양식에 달린 메모는 어떻게 돼요?","keys":["메모","지시","서식","색칠","메모삭제"],"a":["학교 양식에 달린 한/글 메모(예: \"제출 시 메모 삭제\", 글꼴 크기 지시)를 도우미가 읽고 시키는 대로 처리해요. 확인 단계에서 무엇을 읽었는지 보여 줘요.","양식에 \"제출 시 메모 삭제\"라고 적혀 있으면, 그 스위치를 켜 두었을 때 완성 파일에서 메모를 걷어내요. 메모를 남기고 싶으면 끄면 돼요."],"next":["empty","schoolinfo"]},{"id":"schoolinfo","q":"다른 학교 평가계획을 참고할 수 있어요?","keys":["학교알리미","공시","다른학교","참고"],"pose":"wave","a":["확인 단계의 \"이 학교가 공시한 평가계획\"에서 시도, 학교급, 학교 이름을 넣고 **\"받아보기\"** 를 누르면, 학교알리미에 올라온 평가계획을 읽고 그 학교가 어느 칸에 어떻게 적는지 배워요.","이때 밖으로 나가는 것은 **학교 이름뿐**이고, 내 문서는 나가지 않아요. 한 부씩 열어 보느라 몇 분 걸릴 수 있고, 학교 망에서 학교알리미가 막혀 있으면 안 될 수도 있어요."],"next":["memo"]},{"id":"privacy","q":"내 문서가 밖으로 나가나요?","keys":["개인정보","보안","전송","유출","나가","안전","서버","보내"],"pose":"wave","a":["문서 작업은 **내 컴퓨터에서** 이루어져요.","다만 AI를 연결해서 쓰면, 문서에서 뽑아낸 필요한 내용이 **내가 고른 AI 서비스**(예: Gemini, Claude)로 보내져요.","그리고 저 AI선비와 나눈 대화는 어디에도 보내지 않아요."],"next":["connect","noai"]}]},"credit":{"name":"과목선택 시뮬레이터","example":"택4가 무슨 뜻이에요?","bubble":"과목 고르기 어렵죠? <b>AI선비</b>가 같이 골라 볼게요!","hello":["에헴, 반가워요! 저는 **AI선비**예요.","여기서는 내가 가고 싶은 **학과**에 필요한 과목을, **우리 학교에 열리는 과목** 중에서 미리 골라 볼 수 있어요. 처음이라면 \"차근차근 알려 주세요\"를 눌러 보세요!"],"quick":["start","colors","groups","goal","school","undecided","print"],"topics":[{"id":"what","q":"이게 뭐 하는 곳이에요?","keys":["뭐하는","무엇","소개","뭐야","뭐예요","시뮬레이터"],"pose":"wave","a":["고등학교 2·3학년 때 들을 **선택과목을 미리 골라 보는 연습장**이에요.","계열과 학과를 고르면, 그 학과에 필요한 **핵심과목·권장과목**을 우리 학교 과목표(편제표)에서 찾아 색깔로 보여 줘요. 2028학년도 대입을 앞두고 주요 대학이 발표한 자료를 학과별로 정리했어요."],"next":["start","colors"]},{"id":"start","q":"처음부터 차근차근 알려 주세요","keys":["처음","사용법","어떻게","순서","방법","시작","차근차근","하는법"],"a":["좋아요, 순서대로 해 봐요!"],"steps":["**우리 학교 고르기**: 처음 뜨는 \"학교를 선택하세요\" 창에 학교 이름이나 지역(예: 안산)을 써서 우리 학교를 눌러요.","**목표 고르기**: \"내신 2등급 이내\"와 \"내신 3등급 이하\" 중 내 목표에 가까운 것을 눌러요.","**1단계 계열**: 공학, 자연과학, 인문처럼 관심 있는 분야를 눌러요.","**2단계 세부 학과**: 그 아래 나오는 학과 중 하나를 눌러요.","**과목 고르기**: 학기별 과목 중 듣고 싶은 과목을 눌러요. **금색**과 **보라색** 과목을 먼저 살펴보세요.","왼쪽 **\"이수 현황\"** 에서 학기별 학점이 잘 채워졌는지 확인해요.","다 했으면 **\"인쇄\"** 버튼으로 뽑거나 PDF로 저장해요."],"spot":[{"text":"진로 탐색기"}],"next":["colors","groups","goal"]},{"id":"colors","q":"과목 색깔은 무슨 뜻이에요?","keys":["색","금색","보라","파랑","파란","점선","노란","핵심","권장"],"a":["색깔마다 뜻이 있어요."],"steps":["**금색**: 핵심과목이에요. 그 학과에 가려면 사실상 꼭 들어야 해요.","**보라색**: 권장과목이에요. 들으면 유리해요.","**파란색**: 내가 고른 과목이에요.","**점선**: 우리 학교에는 열리지 않는 과목이에요. 공동교육과정 같은 다른 방법을 알아봐야 해요."],"next":["groups","joint"]},{"id":"groups","q":"\"그룹1 · 택4\"는 무슨 뜻이에요?","keys":["그룹","택","택1","택4","몇개","몇과목","개수"],"a":["그 묶음 안에서 **정해진 개수만큼** 고르라는 뜻이에요. \"택4\"면 4과목, \"택1\"이면 1과목을 골라요.","옆에 있는 \"0 / 4\" 같은 숫자가 지금 몇 개 골랐는지 알려 줘요.","**\"두 학기\"** 라고 적힌 과목은 두 학기에 열리지만, 그중 **한 학기만** 들으면 돼요."],"next":["credits","colors"]},{"id":"credits","q":"이수 현황(학점)은 어떻게 봐요?","keys":["학점","이수","현황","몇학점"],"a":["왼쪽 **\"이수 현황\"** 에 내가 고른 선택과목의 학점이 학기별로 더해져 보여요. 과목 옆 숫자(예: 3학점)가 모두 더해지는 거예요.","고른 과목을 한 번 더 누르면 선택이 풀려요. 모두 지우고 싶으면 \"선택 전체 초기화\"를 눌러요."],"spot":[{"text":"이수 현황"}],"next":["reset","print"]},{"id":"goal","q":"내신 2등급·3등급 버튼은 뭐예요?","keys":["등급","내신","목표","수도권","지역거점","2등급","3등급","5등급"],"a":["목표 대학에 따라 필요한 과목 기준이 조금 달라서 나눠 놓았어요.","**내신 2등급 이내**는 서울대·고려대·경희대 같은 수도권 주요 대학 기준, **내신 3등급 이하**는 경북대·부산대·전남대 같은 지역거점·일반 대학 기준이에요."],"tip":"등급은 목표를 잡기 위한 기준일 뿐이에요. 가고 싶은 대학이 정해졌다면 그 대학 입학처 안내를 꼭 확인하세요. 2028학년도부터 내신은 5등급 상대평가예요.","spot":[{"text":"내신 2등급 이내"}],"next":["start","exam"]},{"id":"school","q":"학교는 어떻게 바꿔요?","keys":["학교변경","학교바꾸","바꾸","변경","학교선택","검색","다른학교"],"a":["화면 위쪽 **\"학교 변경\"** 버튼을 누르면 학교 고르는 창이 다시 열려요. 학교 이름이나 지역 이름으로 검색해서 눌러요."],"spot":[{"text":"학교 변경"}],"next":["verify","notmine"]},{"id":"verify","q":"\"대조 확인 / 확인 필요 / 대조 못 함\"은 뭐예요?","keys":["대조","확인필요","대조못함","대조확인"],"a":["학교 이름 옆 표시는 과목표가 얼마나 정확한지 알려 줘요."],"steps":["**대조 확인**: 원본과 비교해 보니 틀린 곳이 없어요.","**확인 필요**: 원본과 다른 곳이 있어서 원본을 봐야 해요.","**대조 못 함**: 비교할 원본이 없었다는 뜻이에요. 틀렸다는 뜻은 아니에요."],"tip":"과목표(편제표)는 학교알리미에 공시된 2026학년도 자료예요.","next":["notmine"]},{"id":"notmine","q":"우리 학교가 없거나 과목이 달라요","keys":["학교가없","우리학교가없","학교없","안나와","목록에없","다르","틀려","잘못","편제표","추가","등록","올리"],"pose":"think","a":["학교 고르는 창에서 **\"우리 학교가 없거나 표가 다른가요?\"** 를 누르면, 학교 과목표(편제표) 파일(엑셀·한글·PDF)을 올려서 바로 쓸 수 있어요. 5분쯤 걸려요.","이미 쓰고 있는 학교의 표가 다르면, 위쪽 **\"편집\"** 메뉴에서 \"고친 편제표 보내기\"로 알려 주세요."],"spot":[{"text":"우리 학교가 없거나"},{"text":"학교 변경"}],"next":["school"]},{"id":"joint","q":"공동교육과정이 뭐예요?","keys":["공동교육","공동","온라인","미개설","안열리"],"pose":"wave","a":["우리 학교에 없는 과목을 **다른 학교 학생들과 함께**, 또는 **온라인으로** 듣는 수업이에요.","신청 방법과 시간은 지역과 학교마다 달라서 담임 선생님이나 교육과정 담당 선생님께 물어보세요."],"next":["colors"]},{"id":"undecided","q":"아직 학과를 못 정했어요","keys":["못정","모르겠","고민","진로","꿈","적성","정하지","모름","꿈이없","없어요","하고싶은게"],"pose":"think","a":["괜찮아요! 아직 못 정한 친구들이 훨씬 많아요. 이렇게 해 보세요."],"steps":["1단계 계열 버튼을 하나씩 눌러 보며 어떤 학과들이 있는지 구경해요.","관심 가는 학과 두세 개를 골라 **금색 핵심과목**을 비교해요. 여러 학과에 겹치는 과목부터 들어 두면 선택지가 넓어져요.","좋아하거나 잘하는 과목에서 출발해도 좋아요.","결과 화면을 담임 선생님, 진로 선생님과 함께 보며 이야기해 보세요."],"spot":[{"text":"1단계"},{"text":"진로 탐색기"}],"next":["start","colors"]},{"id":"print","q":"결과를 저장하거나 인쇄하려면?","keys":["인쇄","저장","pdf","출력","프린트","뽑"],"a":["위쪽 **\"인쇄\"** 버튼을 눌러요. 인쇄 창에서 프린터 대신 **\"PDF로 저장\"** 을 고르면 파일로 저장할 수 있어요."],"spot":[{"text":"인쇄"}],"next":["reset"]},{"id":"reset","q":"처음부터 다시 고르고 싶어요","keys":["초기화","다시고르","처음부터다시","리셋","지우","취소"],"a":["왼쪽 **\"선택 전체 초기화\"** 를 누르면 고른 과목이 모두 지워져요. 하나만 빼고 싶으면 그 과목을 한 번 더 누르면 돼요."],"spot":[{"text":"선택 전체 초기화"}],"next":["start"]},{"id":"dark","q":"화면이 너무 밝아요","keys":["어둡","밝아","다크","눈부","야간"],"a":["위쪽 **\"화면\"** 버튼을 누르면 밝은 화면과 어두운 화면을 바꿀 수 있어요."],"spot":[{"sel":"header button","text":"화면"}]},{"id":"exam","q":"이대로 하면 대학에 붙나요?","keys":["대학","합격","입시","붙","정확","믿어"],"pose":"think","a":["이 시뮬레이터는 대학들이 발표한 자료를 학과별로 정리한 **길잡이**예요. 합격을 약속하지는 않아요.","대학마다, 해마다 기준이 바뀔 수 있으니 가고 싶은 대학이 생기면 그 대학 **입학처 안내**를 꼭 확인하세요."],"next":["goal"]}]},"attendance":{"name":"결석 신고서 · 전자 서명","example":"결석 신고서는 어떻게 써요?","bubble":"신고서 쓰는 게 처음이에요? <b>AI선비</b>가 알려 줄게요!","hello":["에헴, 반가워요! 저는 **AI선비**예요.","여기서는 결석·지각·조퇴 신고서와 체험학습 서류를 **종이 대신 휴대폰**으로 쓰고, 서명해서 담임 선생님께 보낼 수 있어요. 무엇을 하러 왔나요?"],"quick":["what","absent","trip","tripresult","kinds","teacher"],"contexts":[{"match":"student\\.html","bottom":92,"hello":["결석 신고서를 쓰러 왔군요! 저는 **AI선비**예요.","**노란 칸**만 차례대로 채우면 돼요. 막히면 저를 불러 주세요."],"quick":["absent","kinds","evidence","sign","fix"]},{"match":"trip\\.html","bottom":92,"hello":["체험학습 서류를 쓰러 왔군요! 저는 **AI선비**예요.","다녀오기 **전**에는 \"신청서\", 다녀온 **뒤**에는 \"결과보고서\"를 써요."],"quick":["trip","tripresult","sign","fix"]},{"match":"admin\\.html","hello":["선생님, 어서 오세요! 저는 **AI선비**예요.","제출된 서류를 모아 보고 확인서·통보서를 쓰는 화면이에요."],"quick":["teacher","teachersign","password"]}],"topics":[{"id":"what","q":"여기서 뭘 할 수 있어요?","keys":["뭐하는","무엇","소개","뭐야","뭐예요","할수있"],"pose":"wave","a":["세 가지를 할 수 있어요."],"steps":["**결석 신고서**: 결석·지각·조퇴·결과 신고서를 쓰고 학생과 보호자가 직접 서명해 담임 선생님께 내요.","**교외체험학습**: 다녀오기 전 신청서, 다녀온 뒤 결과보고서·별지를 써서 내요.","**교사 화면**: 선생님이 제출된 서류를 월별로 모아 보고, 확인서·통보서를 쓰고 인쇄해요."],"next":["absent","trip","teacher"]},{"id":"absent","q":"결석 신고서는 어떻게 써요?","keys":["결석","신고서","지각","조퇴","쓰는법","작성","어떻게"],"a":["어렵지 않아요. 순서대로 해 봐요!"],"steps":["첫 화면에서 **\"신고서 작성하기\"** 를 눌러요.","**노란 칸**을 누르거나 아래 **\"다음 빈칸 작성 ▶\"** 을 누르면 채울 칸으로 하나씩 안내해 줘요. 학년·반·번호·이름, 결석 종류, 날짜, 사유를 적어요.","위쪽 \"0/19 항목\" 숫자로 얼마나 채웠는지 볼 수 있어요.","**학생**과 **보호자**가 각자 직접 서명해요.","진단서나 소견서가 있으면 사진을 찍어 올려요(최대 3장).","내용을 확인하고 **\"제출하기\"** 를 누르면 끝!"],"tip":"결재란과 확인서는 담임 선생님이 쓰는 칸이라 비워 둬요. 화면이 작으면 두 손가락으로 벌려 확대할 수 있어요.","spot":[{"text":"다음 빈칸 작성"},{"text":"신고서 작성하기"}],"next":["kinds","evidence","sign"]},{"id":"kinds","q":"질병·인정·기타, 결석·지각·조퇴·결과가 뭐예요?","keys":["질병","인정","기타","종류","차이","결과","구분","미인정","체크"],"a":["체크할 칸이 두 줄이에요. 첫 줄은 **왜** 빠졌는지, 둘째 줄은 **얼마나** 빠졌는지예요."],"steps":["**질병**: 아파서 빠졌을 때","**인정**: 학교가 출석으로 인정해 주는 이유일 때 (예: 집안 경조사, 법으로 정한 감염병 등)","**기타**: 위 두 가지에 해당하지 않을 때","**결석**: 하루 종일 학교에 못 갔을 때","**지각**: 늦게 왔을 때","**조퇴**: 일찍 집에 갔을 때","**결과**: 학교에는 있었지만 수업 일부(몇 교시)를 빠졌을 때"],"tip":"어느 칸인지 헷갈리면 담임 선생님께 먼저 물어보세요. 자세한 기준은 학교마다 조금씩 달라요.","next":["absent","evidence"]},{"id":"evidence","q":"증빙 서류는 꼭 내야 해요?","keys":["증빙","진단서","소견서","처방전","사진","첨부","진료확인서","병원"],"a":["아파서 결석했다면 **진단서, 소견서, 진료확인서, 처방전** 같은 서류가 있으면 좋아요. 화면 아래 **\"사진 추가\"** 로 최대 3장까지 올릴 수 있어요.","원본 서류가 있으면 담임 선생님께도 드려요.","진단서나 소견서가 없으면 **담임 의견서**와 **학부모 의견서**에 이유를 분명하게 적어야 해요."],"spot":[{"text":"사진 추가"}],"next":["sign","absent"]},{"id":"sign","q":"서명은 어떻게 해요?","keys":["서명","싸인","사인","도장","보호자서명","부모님"],"a":["서명 칸이 나오면 손가락(컴퓨터는 마우스)으로 내 이름을 쓰듯 그리면 돼요.","**학생 서명은 학생 본인이**, **보호자 서명은 보호자가** 꼭 직접 해야 해요. 다른 사람이 대신 서명하면 안 돼요."],"tip":"보호자와 함께 있을 때 신고서를 쓰면 한 번에 끝낼 수 있어요.","next":["fix","absent"]},{"id":"fix","q":"잘못 썼어요. 고칠 수 있어요?","keys":["수정","고치","잘못","틀렸","다시","실수"],"pose":"think","a":["**제출하기 전**이라면 확인 화면의 **\"수정하기\"** 를 눌러 고칠 수 있어요.","**제출한 뒤**에는 고칠 수 없어요. 잘못 냈다면 담임 선생님께 말씀드리세요."],"next":["absent"]},{"id":"trip","q":"교외체험학습 신청서는 어떻게 써요?","keys":["체험학습","체험","여행","가족여행","신청서","교외","현장학습"],"steps":["첫 화면 교외체험학습에서 **\"신청서 작성\"** 을 눌러요.","**\"① 신청서 (체험학습 전)\"** 이 선택된 상태에서 노란 칸을 채워요. \"다음 빈칸 작성 ▶\"을 누르면 차례대로 안내해 줘요.","학생과 보호자가 각자 직접 서명하고 **\"제출하기\"** 를 눌러요."],"tip":"체험학습 **3일 전까지** 내야 해요. 그리고 제출했다고 바로 허가된 게 아니에요! 담임 선생님께 **허가 통보(또는 문자)** 를 받은 뒤에 다녀와야 해요.","spot":[{"text":"① 신청서"},{"text":"신청서 작성"}],"next":["tripresult","sign"]},{"id":"tripresult","q":"다녀온 뒤 결과보고서는요?","keys":["결과보고서","보고서","별지","다녀온","다녀와","갔다와"],"steps":["첫 화면에서 **\"결과보고서·별지 작성\"** 을 누르거나, 체험학습 화면에서 **\"② 결과보고서 (다녀온 후)\"** 를 눌러요.","어디서 무엇을 보고 배웠는지 칸을 채워요.","**부모님과 함께 찍은 사진을 2장 이상** 올려요.","서명하고 \"제출하기\"를 눌러요."],"tip":"다녀온 뒤 **7일 안에** 내야 해요.","spot":[{"text":"② 결과보고서"},{"text":"결과보고서·별지 작성"}],"next":["trip","sign"]},{"id":"teacher","q":"교사 화면은 어떻게 써요?","keys":["교사","선생님","담임","관리","수합","모아","월별","확인서","통보서","담임인데","선생님인데","교사인데","교사용","담임용"],"steps":["첫 화면에서 **\"교사 화면 들어가기\"** 를 눌러요.","비밀번호를 넣고 \"들어가기\"를 눌러요.","**담임 이름**을 입력해 저장해요. 통보서에 이 이름이 들어가요.","제출된 결석 신고서·출석의견서와 체험학습 신청서·결과보고서를 **월별로** 모아 봐요.","확인서와 통보서를 작성하고 인쇄해요."],"tip":"처음에 **\"담임 서명 등록\"** 을 해 두면 확인서와 통보서를 저장할 때 서명이 찍혀요.","spot":[{"text":"교사 화면 들어가기"},{"text":"들어가기"}],"next":["teachersign","password"]},{"id":"teachersign","q":"담임 서명은 어떻게 등록해요?","keys":["담임서명","서명등록","등록"],"a":["교사 화면 위쪽의 **\"담임 서명 등록\"** 을 눌러 서명을 한 번 그려 두면, 확인서와 통보서를 저장할 때 그 자리에 서명이 찍혀요. 바꾸고 싶으면 \"담임 서명 다시 등록\"을 눌러요."],"spot":[{"text":"담임 서명"}],"next":["teacher"]},{"id":"password","q":"교사 화면 비밀번호를 몰라요","keys":["비번","비밀번호","암호","로그인"],"pose":"think","a":["교사 화면 비밀번호는 이 서비스를 학교에 맞게 준비한 **담당 선생님**께 물어보세요. 학생은 교사 화면에 들어갈 필요가 없어요."],"next":["teacher"]},{"id":"privacy","q":"내 정보는 어디로 가요?","keys":["개인정보","보안","전송","유출","어디로","누가봐","서버","체험모드"],"pose":"wave","a":["제출한 신고서와 사진은 **담임 선생님이 볼 수 있도록** 학교용 저장 공간으로 보내져요.","화면에 \"체험 모드\"라고 뜨면 아직 서버에 연결되지 않은 상태라, 제출 내용이 **이 기기에만** 저장돼요.","저 AI선비와 나눈 대화는 어디에도 보내지 않아요."],"next":["absent"]}]},"saengibu":{"name":"생기부 감사관","example":"위험과 주의는 뭐가 달라요?","bubble":"세특 점검이 처음이세요? <b>AI선비</b>가 안내해 드려요!","hello":["에헴, 어서 오세요! 저는 **AI선비**예요.","생기부 감사관은 **세특(과목별 세부능력 및 특기사항)** 글이 2026 기재요령에 맞는지 점검해 줘요. 쓰면 안 되는 말은 바로, 아쉬운 표현은 꼼꼼히 찾아 드려요."],"quick":["start","practice","result","fix","class","plag","privacy"],"topics":[{"id":"what","q":"이게 뭐 하는 프로그램이에요?","keys":["뭐하는","무엇","소개","뭐야","뭐예요","감사관"],"pose":"wave","a":["선생님이 쓴 세특을 **2026학년도 학교생활기록부 기재요령**에 맞춰 점검하는 도구예요.","**생기부 감사관**은 기재 금지 표현과 고치면 좋은 표현을 찾고, **표절감사관**은 다른 글과 얼마나 겹치는지(유사도)를 봐요. 위쪽 버튼으로 두 도구를 오갈 수 있어요."],"next":["start","plag"]},{"id":"start","q":"세특 한 편 감사하는 법","keys":["처음","사용법","어떻게","순서","방법","시작","차근차근","개별","한편"],"a":["순서대로 해 볼까요?"],"steps":["위쪽에서 **\"생기부 감사관\"** 을 고르고 **\"개별 감사\"** 탭인지 확인해요.","**\"세특 원문\"** 칸에 검사할 세특을 붙여 넣어요. 칸 아래에 분량(byte)이 보여요. 상한은 1,500byte, 한글로 약 500자예요.","(선택) **\"원자료 대조 감사\"** 를 열어 발표 기록, 관찰 메모, 보고서 내용을 넣으면 세특 문장에 근거가 있는지도 확인해요.","**\"감사 시작\"** 을 눌러요.","결과에서 **노란 형광펜**을 누르면 왜 문제인지와 고치는 방법이 바로 열려요.","다 고쳤으면 **\"나이스용 복사\"** 를 눌러 나이스에 붙여 넣어요."],"spot":[{"text":"감사 시작"},{"text":"다른 세특 감사하기"}],"next":["practice","result","source"]},{"id":"practice","q":"먼저 연습해 보고 싶어요","keys":["예시","연습","샘플","체험","테스트","구경"],"pose":"cheer","a":["좋은 생각이에요! **\"예시 불러오기\"** 를 누르면 연습용 세특이 들어가요. 그다음 \"감사 시작\"을 눌러 결과 화면을 구경해 보세요."],"spot":[{"text":"예시 불러오기"},{"text":"다른 세특 감사하기"}],"next":["result","start"]},{"id":"result","q":"결과 화면은 어떻게 봐요?","keys":["결과","점수","위험","주의","형광펜","품질","7대","기준","교체","다른점","차이"],"a":["결과 화면에서 이것들을 보면 돼요."],"steps":["**품질 점수**: 100점에 가까울수록 좋은 기록이에요.","**위험(기재 금지)**: 대회·수상, 공인어학시험, 모의고사 성적, 논문, 대학·기관·상호·강사 이름, 자격증, 방과후학교, 해외 활동, 부모 직업, 장학금, 분량 초과 등이에요. 남아 있으면 나이스에 입력할 수 없어서 **꼭** 고쳐야 해요.","**주의(수정 권장)**: 고치면 좋아지는 표현이에요. 근거 없이 \"뛰어남\"이라고 쓰기, 추상적인 말, 교과 지식만 나열, 학생 소감 말투, 과장 등이에요.","**7대 감사기준**: 근거성·구체성·고유성·과정성·성장성·중복안전성·과장안전성을 막대로 보여 줘요.","**\"이름 바꿔도 되는 세특인가?\"**: 다른 학생 이름을 넣어도 말이 된다면, 그 학생만의 모습이 부족하다는 뜻이에요."],"next":["fix","byte"]},{"id":"fix","q":"고치는 방법은요?","keys":["수정","고치","편집","되돌","원문","복사","나이스","처방"],"a":["형광펜을 누르면 **처방**(고칠 방향)이 열려요. 그다음 이렇게 해요."],"steps":["**\"편집\"** 을 눌러 직접 고쳐요.","**\"되돌리기\"** 는 한 단계 전으로, **\"원문\"** 은 처음 글로 돌아가요.","다 고쳤으면 **\"나이스용 복사\"** 를 눌러요."],"tip":"수정은 선생님이 확인한 사실만으로 해요. 원문에 없는 사실이 끼어들면 \"사실 가드\"가 잡아요. 결과는 언제나 초안이니, 나이스에 넣기 전에 허위·과장이 없는지 꼭 직접 확인하세요(기재요령 19쪽 5-다).","spot":[{"text":"나이스용 복사"}],"spotMiss":"아직 감사 결과가 없어서 그 버튼이 안 보여요. 먼저 \"감사 시작\"을 눌러 주세요.","next":["result","report"]},{"id":"source","q":"원자료 대조 감사가 뭐예요?","keys":["원자료","대조","근거","관찰","관찰메모","증거"],"a":["세특 문장이 **실제 기록**(발표 기록, 교사 관찰 메모, 탐구보고서 등)에 근거가 있는지 이어서 확인하는 기능이에요.","결과의 **\"증거 연결 분석\"** 에서 학생 행동 → 학생 사고 → 교사 평가가 근거로 이어지는지 보여 줘요. 넣지 않아도 감사는 돼요."],"spot":[{"text":"원자료 대조"}],"next":["start"]},{"id":"byte","q":"분량(byte) 제한이 뭐예요?","keys":["byte","바이트","글자수","분량","500자","1500","길이"],"a":["나이스 세특 칸은 **1,500byte**까지 들어가요. 한글은 한 글자에 3byte라서 **약 500자**예요. 칸 아래 숫자로 지금 몇 byte인지 볼 수 있고, 넘치면 \"위험\"으로 알려 줘요."],"next":["result"]},{"id":"class","q":"한 반을 한꺼번에 검사하려면?","keys":["학급","한반","한꺼번","엑셀","csv","xlsx","여러명","응급실","일괄","전체학생","반전체","한번에","전체"],"steps":["**\"학급 감사 · 세특 응급실\"** 탭을 눌러요.","학급 이름을 적어요.","엑셀에서 **학번 · 이름 · 세특 · 원자료(선택)** 열을 복사해 붙여 넣거나, **\"파일 올리기 (CSV·XLSX)\"** 로 파일을 올려요.","**\"학급 감사 시작\"** 을 눌러요. 기재 금지 사항은 바로, 나머지는 학생마다 꼭 필요한 질문만 보여 줘요."],"tip":"파일은 10MB까지, XLSX는 첫 번째 시트만 읽어요. XLS 파일은 XLSX나 CSV로 바꿔서 올려요. 처음이면 \"예시 학급 불러오기\"로 연습해 보세요.","spot":[{"text":"학급 감사 · 세특 응급실"},{"text":"생기부 감사관"}],"next":["dict","privacy"]},{"id":"dict","q":"\"내 사전\"은 뭐예요?","keys":["사전","상호명","앱이름","단어","내사전","학원"],"a":["우리 학교에서 자주 나오는 **상호명이나 앱 이름**을 추가하는 곳이에요. 추가하면 다음 감사부터 \"위험(상호명)\"으로 잡히고, 적어 둔 대체어로 바로 바뀌어요.","**\"내보내기(복사)\"** 와 **\"가져오기(붙여넣기)\"** 로 동료 선생님과 사전을 주고받을 수 있어요."],"spot":[{"text":"내 사전"}],"next":["class"]},{"id":"plag","q":"표절감사관(유사도 검사)은 어떻게 써요?","keys":["표절","유사도","베낌","베꼈","복붙","카피","ai탐지","ai작성","gpt"],"steps":["위쪽 **\"표절감사관\"** 을 눌러요.","\"검사할 글\" 칸에 글을 붙여 넣거나 **\"원문 파일 불러오기\"** 로 파일(TXT·DOCX·HWPX·텍스트 PDF)을 올려요.","입력을 멈추면 **1초 뒤 자동으로** 검사해요. 기본은 6어절이 연속으로 같으면 겹친다고 봐요.","\"비교자료 직접 추가\"로 비교할 글을 넣을 수 있어요. 필요하면 \"위키백과 공개자료도 찾아 비교\"를 켜요(이때 주제어만 위키백과로 보내요)."],"tip":"유사도는 표절 판정이 아니에요. 출처와 맥락을 함께 보세요. \"AI 작성 탐지\"는 실험 기능이라, 점수만으로 AI 사용이나 부정행위를 판단하면 안 돼요.","spot":[{"text":"표절감사관"}],"next":["privacy","start"]},{"id":"report","q":"결과를 저장하거나 공유하려면?","keys":["보고서","이미지","인쇄","저장","공유","출력"],"a":["결과 화면의 **\"보고서 이미지\"** 로 그림 파일을, **\"인쇄\"** 로 종이나 PDF로 남길 수 있어요. **\"+ 다른 세특 감사하기\"** 를 누르면 새 세특을 검사해요."],"spot":[{"text":"보고서 이미지"}],"spotMiss":"아직 감사 결과가 없어서 그 버튼이 안 보여요. 먼저 \"감사 시작\"을 눌러 주세요.","next":["fix"]},{"id":"privacy","q":"학생 기록이 밖으로 나가나요?","keys":["개인정보","보안","전송","유출","나가","안전","서버","보내"],"pose":"wave","a":["생기부 감사관은 **내 브라우저 안에서만** 검사해요. 학생 기록은 이 브라우저 밖으로 나가지 않아요.","표절감사관의 기본 검사도 이 컴퓨터에서 처리돼요. \"위키백과 공개자료\" 검색을 켤 때만 **주제어**가 밖으로 나가요.","피드백 \"보내기\"는 글이 담긴 창이 열리고 선생님이 확인한 뒤에 보내져요. 학생 이름이나 기록은 넣지 마세요."],"next":["start"]}]}};

  function detectApp() {
    var a = SCRIPT && SCRIPT.getAttribute('data-app');
    if (a && DATA[a]) return a;
    var u = location.href;
    if (/pyeongga/.test(u)) return 'pyeongga';
    if (/games\/credit|elective-subject/.test(u)) return 'credit';
    if (/attendance-report/.test(u)) return 'attendance';
    if (/saengibu-auditor/.test(u)) return 'saengibu';
    return null;
  }
  var APP_ID = detectApp();
  if (!APP_ID) return;
  var APP = DATA[APP_ID];
  var CTX = null;
  (APP.contexts || []).some(function (c) {
    if (new RegExp(c.match).test(location.pathname + location.hash)) { CTX = c; return true; }
    return false;
  });
  var HELLO = (CTX && CTX.hello) || APP.hello;
  var QUICK = (CTX && CTX.quick) || APP.quick;
  var HOME = {
    bottom: +(SCRIPT && SCRIPT.getAttribute('data-bottom')) || (CTX && CTX.bottom) || APP.bottom || 14,
    right: +(SCRIPT && SCRIPT.getAttribute('data-right')) || APP.right || 14
  };
  var REDUCED = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;

